theorem thm_GAR : 
  let f : ℝ → ℝ := fun x => 2 * x^2 + 8 * x + 33 - 3 * Real.sqrt (x^2 + 4 * x + 9)
  let consecutive_decreasing (n : ℕ) : Prop := 
    ∃ a b c : ℕ, a ≥ 1 ∧ a ≤ 9 ∧ b ≤ 9 ∧ c ≤ 9 ∧ 
    a = b + 1 ∧ b = c + 1 ∧ n = 100 * a + 10 * b + c
  let reverse_digits (n : ℕ) : ℕ := 
    let a := n / 100
    let b := (n / 10) % 10  
    let c := n % 10
    100 * c + 10 * b + a
  let g (n : ℕ) : ℝ := f (n - 198 : ℝ) + (n - reverse_digits n : ℝ)
  ∃ min_val : ℝ, (∀ n : ℕ, consecutive_decreasing n → g n ≥ min_val) ∧ 
  (∃ n₀ : ℕ, consecutive_decreasing n₀ ∧ g n₀ = min_val) := by

theorem thm_GAR : 
  let y : ℝ → ℝ := fun x => x^2 / 4 - (Real.log x) / 2
  let dy_dx : ℝ → ℝ := fun x => x / 2 - 1 / (2 * x)
  let arc_length := ∫ x in (1 : ℝ)..(2 : ℝ), Real.sqrt (1 + (dy_dx x)^2)
  let y_at_e := y (Real.exp 1)
  let arithmetic_result := 1 / (1/2 + 1/y_at_e)
  ∃ (final_answer : ℝ), 
    arc_length = final_answer ∧ 
    arithmetic_result = final_answer ∧
    final_answer = 4 / (1 + (Real.exp 1)^2) := by
